import json, sys

CUTOFF = "2026-02-28T23:59:59Z"

def load(path):
    with open(path) as f:
        outer = json.load(f)
    return json.loads(outer["result"])

def le_cutoff(ts):
    # ISO timestamps compare lexicographically when same format (Z suffix)
    return ts is not None and ts <= CUTOFF

def commits(path):
    data = load(path)
    # filter by commit date (committer/author date). Use commit.committer.date or commit.author.date
    filt = []
    for c in data:
        d = None
        commit = c.get("commit", {})
        d = (commit.get("committer") or {}).get("date") or (commit.get("author") or {}).get("date")
        if d is None or le_cutoff(d):
            filt.append(c)
    return {
        "commit_count": len(filt),
        "commit_first_sha": filt[0].get("sha") if filt else None,
        "commit_last_sha": filt[-1].get("sha") if filt else None,
    }

def reviews(path):
    data = load(path)
    filt = [r for r in data if le_cutoff(r.get("submitted_at"))]
    dates = [r["submitted_at"] for r in filt if r.get("submitted_at")]
    people = []
    for r in filt:
        lg = (r.get("user") or {}).get("login")
        if lg and lg not in people: people.append(lg)
    states = []
    for r in filt:
        st = r.get("state")
        if st and st not in states: states.append(st)
    return {
        "review_count": len(filt),
        "review_first_date": min(dates) if dates else None,
        "review_last_date": max(dates) if dates else None,
        "review_people": people,
        "review_states": states,
        "approved_present": any(r.get("state") == "APPROVED" for r in filt),
    }

def inline(path):
    data = load(path)
    filt = [c for c in data if le_cutoff(c.get("created_at"))]
    dates = [c["created_at"] for c in filt if c.get("created_at")]
    people = []
    for c in filt:
        lg = (c.get("user") or {}).get("login")
        if lg and lg not in people: people.append(lg)
    files = []
    for c in filt:
        p = c.get("path")
        if p and p not in files: files.append(p)
    return {
        "inline_count": len(filt),
        "inline_first_date": min(dates) if dates else None,
        "inline_last_date": max(dates) if dates else None,
        "inline_people": people,
        "inline_files": files[:15],
    }

def general(path):
    data = load(path)
    filt = [c for c in data if le_cutoff(c.get("created_at"))]
    dates = [c["created_at"] for c in filt if c.get("created_at")]
    people = []
    for c in filt:
        lg = (c.get("user") or {}).get("login")
        if lg and lg not in people: people.append(lg)
    return {
        "general_count": len(filt),
        "general_first_date": min(dates) if dates else None,
        "general_last_date": max(dates) if dates else None,
        "general_people": people,
    }

def timeline(path):
    data = load(path)
    # An event has a timestamp under created_at (or submitted_at for reviews)
    def ts_of(e):
        return e.get("created_at") or e.get("submitted_at") or e.get("date")
    # Exclude events dated after cutoff from ALL (counts/dates/people)
    filt = []
    for e in data:
        t = ts_of(e)
        if t is None or le_cutoff(t):
            filt.append(e)
    dated = [ts_of(e) for e in filt if ts_of(e)]
    people = []
    for e in filt:
        lg = (e.get("actor") or {}).get("login") or (e.get("user") or {}).get("login")
        if lg and lg not in people: people.append(lg)
    events = []
    for e in filt:
        ev = e.get("event")
        if ev and ev not in events: events.append(ev)
    return {
        "lifecycle_count": len(filt),
        "lifecycle_first_date": min(dated) if dated else None,
        "lifecycle_last_date": max(dated) if dated else None,
        "lifecycle_people": people,
        "lifecycle_events": events,
        "review_request_event_present": any(e.get("event") == "review_requested" for e in filt),
    }

if __name__ == "__main__":
    kind = sys.argv[1]
    path = sys.argv[2]
    fn = {"commits": commits, "reviews": reviews, "inline": inline, "general": general, "timeline": timeline}[kind]
    print(json.dumps(fn(path)))

