def joinp(lst):
    return ', '.join(lst) if lst else ''

def daterange(a, b):
    if a and b:
        return f"{a} → {b}" if a != b else a
    return a or b or ''

rows = []
flag_counter = {'NO_SUBMITTED_REVIEW':0,'NO_INLINE_REVIEW_DISCUSSION':0,'NO_GENERAL_CONVERSATION':0,'NO_REVIEW_REQUEST_EVENT':0,'MULTI_COMMIT_WITHOUT_APPROVAL':0,'NONE':0}

