    # commits
    if r['commit_count'] == 0:
        commits = 'NONE FOUND'
    else:
        commits = f"{r['commit_count']} commit(s); first {r['commit_first_sha']}; last {r['commit_last_sha']}"
    # reviews
    if r['review_count'] == 0:
        reviews = 'NONE FOUND'
    else:
        reviews = f"{r['review_count']} review(s); {daterange(r['review_first_date'], r['review_last_date'])}; people: {joinp(r['review_people'])}; states: {joinp(r['review_states'])}"
    # inline
    if r['inline_count'] == 0:
        inline = 'NONE FOUND'
    else:
        inline = f"{r['inline_count']} comment(s); {daterange(r['inline_first_date'], r['inline_last_date'])}; people: {joinp(r['inline_people'])}; files: {joinp(r['inline_files'])}"
    # general
    if r['general_count'] == 0:
        general = 'NONE FOUND'
    else:
        general = f"{r['general_count']} comment(s); {daterange(r['general_first_date'], r['general_last_date'])}; people: {joinp(r['general_people'])}"
    # lifecycle
    if r['lifecycle_count'] == 0:
        lifecycle = 'NONE FOUND'
    else:
        dr = daterange(r['lifecycle_first_date'], r['lifecycle_last_date'])
        dr = dr if dr else 'undated'
        lifecycle = f"{r['lifecycle_count']} event(s); {dr}; people: {joinp(r['lifecycle_people'])}; events: {joinp(r['lifecycle_events'])}"
    # gap flags
    flags = []
    if r['review_count'] == 0: flags.append('NO_SUBMITTED_REVIEW')
    if r['inline_count'] == 0: flags.append('NO_INLINE_REVIEW_DISCUSSION')
    if r['general_count'] == 0: flags.append('NO_GENERAL_CONVERSATION')
    if not r['review_request_event_present']: flags.append('NO_REVIEW_REQUEST_EVENT')
    if r['commit_count'] > 1 and not r['approved_present']: flags.append('MULTI_COMMIT_WITHOUT_APPROVAL')
    if not flags: flags = ['NONE']
    for fl in flags:
        flag_counter[fl] += 1
    gap = '; '.join(flags)
    # complete: all 5 categories evaluated (each has a result incl NONE FOUND)
    complete = 'TRUE'
    rows.append([
        r['repo'], r['pr_number'], r['title'], r['author'], r['state'],
        'TRUE' if r['merged'] else 'FALSE', url,
        r['created_at'] or '', r['closed_at'] or '', r['merged_at'] or '',
        CUTOFF, commits, reviews, inline, general, lifecycle, gap, complete
    ])

# totals
cf = [r for r in recs if r['repo']=='Combo-Fighters']
dm = [r for r in recs if r['repo']=='game-of-dominoes-backend']
totals = {
    'Combo-Fighters': len(cf),
    'game-of-dominoes-backend': len(dm),
    'Combined': len(recs),
}
print('TOTAL ROWS:', len(rows))
print('Combo-Fighters:', totals['Combo-Fighters'])
print('game-of-dominoes-backend:', totals['game-of-dominoes-backend'])
print('Combined:', totals['Combined'])
print('FLAG COUNTS:', json.dumps(flag_counter, indent=2))
# sanity: unique pr per repo
import collections
seen = collections.Counter((r['repo'], r['pr_number']) for r in recs)
dupes = [k for k,v in seen.items() if v>1]
print('DUPES:', dupes)
print('CF numbers:', sorted(r['pr_number'] for r in cf))
print('DM count check numbers 1..79 present:', sorted(r['pr_number'] for r in dm)==list(range(1,80)))

out = {'header': ['Repo','PR Number','Title','Author','State','Merged','URL','Created At (UTC)','Closed At (UTC)','Merged At (UTC)','Snapshot Cutoff','Commits','Submitted Reviews','Inline Diff Comments','General PR Conversation','Lifecycle History','Gap Flags','All Checks Complete'],
       'rows': rows, 'totals': totals, 'flag_counter': flag_counter}
with open('/app/handoff/register_out.json','w') as fh:
    json.dump(out, fh)
print('WROTE register_out.json')

